macros.\\BookTitle:
%
  \mainmatter
  \renewcommand{\thepage}{\texorpdfstring{\osf{\arabic{page}}}{\arabic{page}}}
  \phantomsection\pdfbookmark[-1]{Main Matter.}{Main Matter}%
  \thispagestyle{plain}
  \begin{center}
    \setlength{\TmpLen}{6pt}%
    \Large ELEMENTS \\[\TmpLen]
    \normalsize OF \\[\TmpLen]
    \Large PLANE TRIGONOMETRY.
  \end{center}
  \bigskip

macros.\\MainMatter:
%
  \FlushRunningHeads
  \InitRunningHeads
  \SetRunningHeads[Elementary Illustrations of]{The Differential and Integral Calculus.}
  \mainmatter
  \BookMark{-1}{Main Matter.}

macros.\\Chapter:
%
  \FlushRunningHeads
  \phantomsection
  \label{chapter:#1}
  \BookMark{0}{Chapter #1}%
  \renewcommand{\ChapNo}{#1}
  \thispagestyle{plain}
%
  \ifthenelse{\equal{}{}}{%
    \ifthenelse{\equal{#1}{IV}}{% Chapters IV, X get asymmetric heading
      \SetCenterHeads[LIMITS OF FUNCTIONS OF A]
      {POSITIVE INTEGRAL VARIABLE}%
    }{% Not Chapter IV
      \ifthenelse{\equal{#1}{X}}{%
        \SetCenterHeads[THE GENERAL THEORY OF THE LOGARITHMIC,]
        {EXPONENTIAL, AND CIRCULAR FUNCTIONS}%
      }{% Not Chapter X, but running head manually specified
        \SetCenterHeads{#2}%
      }%
    }%
  }{% Otherwise, use chapter title as running head
    \SetCenterHeads{}%
  }
  \ChapterSpace
  \section*{\centering CHAPTER #1}
  \subsection*{\centering\normalfont\small #2}

macros.\\Part:
%
  \FlushRunningHeads
  \InitRunningHeads
  % Cross-referencing
  \BookMark{0}{Part #1}
  \addtocontents{toc}{\protect\SectTitle{PART #1}}
  \addtocontents{toc}{\protect\SubsectTitle[\protect\footnotesize]{\MakeUppercase{#2}}}
  % Page heading
  \setboolean{ChapterClear}{false}% Tell \Chapter not to start of a new page
  \ifthenelse{\equal{#1}{I.}}{% Special heading for Part I.
    \begin{center}
      \BookHead
    \end{center}
  }{}% Part II., etc.
  \SectTitle{PART #1}
  \SubsectTitle{#2}

macros.\\Chapter:
%
  % Start on a new page unless we've just started a \Part
  \ifthenelse{\boolean{ChapterClear}}{%
    \FlushRunningHeads
    \InitRunningHeads
  }{% Else we've just started a part; set flag
    \setboolean{ChapterClear}{true}%
  }
  % ToC entry
  \refstepcounter{ChapNo}%
  \phantomsection\label{chap:\theChapNo}%
  \addtocontents{toc}{\protect\ToCLine{\theChapNo}{#1}{#2}}
  % PDF bookmark and running heads
  \ifthenelse{\equal{}{}}{% No manual running head
    \BookMark{1}{#2}
    \SetRunningHeads{#2}
    \ChapHead{#1}{#2}
  }{% Manual running head
    \BookMark{1}{}
    \SetRunningHeads{}
    \ChapHead{#1}{#2}
  }
